import org.apache.commons.lang3.StringUtils;

public class Stopwatch {
    private static final long NANOS_PER_MILLI = 1000_000;
    private String message;
    private long startTimeNanos;
    private long stopTimeNanos;
    private long startTimeMillis;
    private long stopTimeMillis;
    private State runningState;
    private SplitState splitState;

    public enum State {
        UNSTARTED, RUNNING, STOPPED, SUSPENDED
    }

    public enum SplitState {
        UNSPLIT, SPLIT
    }

    public Stopwatch() {
        this.runningState = State.UNSTARTED;
        this.splitState = SplitState.UNSPLIT;
    }

    public long getStartTimeMillis() {
        return startTimeMillis;
    }

    public long getStopTimeMillis() {
        return stopTimeMillis;
    }

    public String toSplitString() {
        final String msgStr = Objects.toString(message, StringUtils.EMPTY);
        final String formattedTime = formatTime(getElapsedTimeNanos());
        return msgStr.isEmpty() ? formattedTime : msgStr + StringUtils.SPACE + formattedTime;
    }

    @Override
    public String toString() {
        final String msgStr = Objects.toString(message, StringUtils.EMPTY);
        final String formattedTime = formatTime(getElapsedTimeNanos());
        return msgStr.isEmpty() ? formattedTime : msgStr + StringUtils.SPACE + formattedTime;
    }

    private long getElapsedTimeNanos() {
        if (runningState == State.RUNNING) {
            return System.nanoTime() - startTimeNanos;
        } else if (runningState == State.STOPPED || runningState == State.SUSPENDED) {
            return stopTimeNanos - startTimeNanos;
        }
        return 0;
    }

    private String formatTime(long nanos) {
        long millis = nanos / NANOS_PER_MILLI;
        long hours = millis / (60 * 60 * 1000);
        millis %= (60 * 60 * 1000);
        long minutes = millis / (60 * 1000);
        millis %= (60 * 1000);
        long seconds = millis / 1000;
        millis %= 1000;

        return String.format("%02d:%02d:%02d.%03d", hours, minutes, seconds, millis);
    }

    // Other methods remain unchanged
}
